// 남긴 것
public interface MemberRepository extends JpaRepository<Member, Long> {
    Page<Member> findByAge(int age, Pageable pageable);
}

--   한 줄이다
--   int offset, int limit 이 Pageable 로
--   List 가 Page 로 바뀌었다


-- 부른다

@Test
@Transactional
void 첫_페이지() {
    PageRequest req = PageRequest.of(0, 5,
            Sort.by(Sort.Direction.DESC, "username"));

    Page<Member> page = memberRepository.findByAge(10, req);

    System.out.println("행:     " + page.getContent().stream()
            .map(Member::getUsername).toList());
    System.out.println("전체:   " + page.getTotalElements());
    System.out.println("페이지: " + page.getTotalPages());
    System.out.println("번호:   " + page.getNumber());
    System.out.println("처음?   " + page.isFirst());
    System.out.println("다음?   " + page.hasNext());
}

