void DTO_변환() {
    Page<Member> page = memberRepository.findByAge(10, PageRequest.of(0, 3));
    Page<MemberDto> dto = page.map(m ->
            new MemberDto(m.getId(), m.getUsername(), null));

    System.out.println("내용: " + dto.getContent());
    System.out.println("전체: " + dto.getTotalElements());
}

